    font_lh("a", 23, 2250, 19, 0, 20);
    font_lh("b", 30, 2999, 38, 0, 40);
    font_lh("c", 25, 2499, 200, 1, 0);
    TEST_ASSERT_EQUAL(199, el("c")->h);
    TEST_ASSERT_EQUAL(49, text_y("b") - text_y("a"));
